args.CommandLine:
$r1 = Invoke-RestMethod -Uri "https://api.github.com/search/repositories?q=mikrotik+stars:>10&sort=stars&order=desc&per_page=30" -Headers @{"User-Agent"="PowerShell"}
$r1.items | Select-Object full_name, stargazers_count, description, clone_url | Format-Table -AutoSize
$r2 = Invoke-RestMethod -Uri "https://api.github.com/search/repositories?q=mikrotik+firewall+OR+security+OR+configuration+OR+scripts&sort=stars&order=desc&per_page=25" -Headers @{"User-Agent"="PowerShell"}
$r2.items | Select-Object full_name, stargazers_count, description, clone_url | Format-Table -AutoSize

$queries = @("mikrotik+firewall", "mikrotik+security", "mikrotik+config", "awesome-mikrotik")
foreach ($q in $queries) {
    Write-Host "=== $q ==="
    $r = Invoke-RestMethod -Uri "https://api.github.com/search/repositories?q=$q&sort=stars&order=desc&per_page=10" -Headers @{"User-Agent"="PowerShell"}
    $r.items | Select-Object full_name, stargazers_count, description | Format-Table -AutoSize
}
